const getShortPath = kernel.func("uint32_t __stdcall GetShortPathNameW(const char16_t *lpszLongPath, _Out_ char16_t *lpszShortPath, uint32_t cchBuffer)")
assert.equal(koffi.sizeof("char16_t"), 2)

await publish({ type: "abi-layout", abi, nativeInput: input.nativeInput })
await publish({ type: "entry-name-abi", codeUnitBytes: 2, finalPathFlags: 0,
  finalPathFlagsMeaning: "FILE_NAME_NORMALIZED | VOLUME_NAME_DOS", sizeThenReadCalls: 2,
  maximumCodeUnits: 32768, outputBufferInitialByte: 165, nativeHandleSource: "Same original NOFOLLOW CreateFileW handle as FileAttributeTagInfo" })

function readWidePath(operation, subject, invoke) {
  const result = { operation, subject, sizeCall: null, readCall: null, path: null, failures: [] }
  try {
    const required = invoke(null, 0)
    const sizeError = lastError()
    result.sizeCall = { suppliedCodeUnits: 0, returnValue: required, lastError: sizeError,
      lastErrorMeaning: required ? "observed-stale-on-size-result" : "failure-code" }
    if (!required) result.failures.push({ kind: "win32", operation, phase: "size", subject, win32Error: sizeError, rawReturn: required })
    else if (!Number.isInteger(required) || required < 1 || required > 32768) result.failures.push({
      kind: "native-buffer-contract", operation, phase: "size", subject, rawReturn: required, maximumCodeUnits: 32768 })
    else {
      const buffer = Buffer.alloc(required * 2, 0xa5)
      const written = invoke(buffer, required)
      const readError = lastError()
      result.readCall = { suppliedCodeUnits: required, returnValue: written, lastError: readError,
        lastErrorMeaning: written ? "observed-stale-on-nonzero-result" : "failure-code",
        completeAllocatedBufferBase64: buffer.toString("base64"), allocatedBytes: buffer.length }
      if (!written) result.failures.push({ kind: "win32", operation, phase: "read", subject, win32Error: readError, rawReturn: written })
      else if (!Number.isInteger(written) || written >= required) result.failures.push({
        kind: "native-buffer-contract", operation, phase: "read", subject, rawReturn: written,
        suppliedCodeUnits: required, reason: "Returned length does not fit original sized buffer; no resize/retry" })
      else {
        result.readCall.terminatorCodeUnit = buffer.readUInt16LE(written * 2)
        result.readCall.returnedUtf16CodeUnits = Array.from({ length: written }, (_, index) => buffer.readUInt16LE(index * 2))
        result.readCall.returnedUtf16LEBase64 = buffer.subarray(0, written * 2).toString("base64")
        result.path = buffer.toString("utf16le", 0, written * 2)
        if (result.readCall.terminatorCodeUnit !== 0 || result.path.includes("\0")) result.failures.push({
          kind: "native-buffer-contract", operation, phase: "termination", subject,
          terminatorCodeUnit: result.readCall.terminatorCodeUnit, embeddedNul: result.path.includes("\0") })
      }
    }
  } catch (error) { result.failures.push({ kind: "host-or-ffi", operation, subject, error: originalError(error) }) }
  result.firstCause = result.failures[0] ?? null
  return result
}

function read(operand, includeEntryName = false) {

  if (!accepted) native.failures.push({ kind: "win32", operation: "GetFileInformationByHandleEx", win32Error: queryError, operand, rawReturn: accepted })
  else if (includeEntryName) {
    native.finalPath = readWidePath("GetFinalPathNameByHandleW", { operand, handle, flags: 0 }, (buffer, count) => getFinalPath(handle, buffer, count, 0))
    native.failures.push(...native.finalPath.failures)
  }
}

  return { library, abi, read,
    readEntryName: (operand) => read(operand, true),
    readShortPath: (operand) => readWidePath("GetShortPathNameW", { operand }, (buffer, count) => getShortPath(operand, buffer, count)),
  }
}
